{{!-- Styling parameters: class, listClass, linkClass --}}
{{#with this as |ghostcnStyles|}}
{{!-- Use inside {{#post}}; Ghost foreach filters internal tags. --}}
{{#foreach tags visibility="public"}}{{#if @first}}<nav class="ghcn-tag-list{{#if ghostcnStyles.class}} {{ghostcnStyles.class}}{{/if}}" aria-label="Post tags"><ul class="ghcn-tag-list__items{{#if ghostcnStyles.listClass}} {{ghostcnStyles.listClass}}{{/if}}">{{/if}}<li><a class="ghcn-tag-list__link{{#if ghostcnStyles.linkClass}} {{ghostcnStyles.linkClass}}{{/if}}" href="{{url}}">{{name}}</a></li>{{#if @last}}</ul></nav>{{/if}}{{/foreach}}
{{/with}}

.ghcn-tag-list { margin-block: 1.5em; }
.ghcn-tag-list__items { display: flex; flex-wrap: wrap; gap: .5em; list-style: none; padding: 0; margin: 0; }
.ghcn-tag-list__link { display: block; padding: .375em .875em; background: var(--muted); color: var(--foreground); border: 1px solid var(--border); border-radius: 999px; font-size: .875em; text-decoration: none; }
.ghcn-tag-list__link:hover { background: var(--secondary); text-decoration: underline; }
.ghcn-tag-list__link:focus-visible { outline: 2px solid var(--ring); outline-offset: 3px; }
